package trap

// Raw ClientHello records extracted from the packet captures of the FoxIO JA4
// repository (https://github.com/FoxIO-LLC/ja4, directory pcap/). The expected
// fingerprints come from the repository's published test data
// (python/test/testdata/<capture>.json).
const (
	// tls12.pcap: JA4 "t13d1715h2_5b57614c22b0_3d5424432f57", SNI contile.services.mozilla.com.
	vectorFoxIOTLS12 = ""
	// tls-non-ascii-alpn.pcapng: the first ALPN value is the two bytes 0xba 0xad.
	// The published JA4 is "t13d151699_8daaf6152771_e5627efa2ab1": the reference
	// tools substitute '9' for non-ASCII ALPN bytes, while the JA4 specification
	// (technical_details/JA4.md) says to use the hex form, which gives "bd". Only
	// the ALPN characters differ; both hashes match.
	vectorFoxIONonASCIIALPN = ""
)
